function replace_mcqs(int $order,string $title,array $questions):void{$db=db();$lesson=query_one("SELECT l.id FROM lessons l JOIN grades g ON g.id=l.grade_id JOIN subjects s ON s.id=l.subject_id WHERE g.grade_number=10 AND s.name_en='Buddhism' AND l.medium='Sinhala' AND l.display_order=? AND l.status='active' LIMIT 1",'i',[$order]);if(!$lesson)throw new RuntimeException("Grade 10 Buddhism lesson $order was not found.");$quiz=query_one("SELECT id FROM quizzes WHERE lesson_id=? AND status='active' ORDER BY id LIMIT 1",'i',[(int)$lesson['id']]);if(!$quiz)throw new RuntimeException("Lesson $order quiz was not found.");$quizId=(int)$quiz['id'];$answers=$db->prepare("DELETE qa FROM quiz_answers qa JOIN quiz_questions qq ON qq.id=qa.question_id WHERE qq.quiz_id=? AND qq.activity_type='challenge'");$answers->bind_param('i',$quizId);$answers->execute();$delete=$db->prepare("DELETE FROM quiz_questions WHERE quiz_id=? AND activity_type='challenge'");$delete->bind_param('i',$quizId);$delete->execute();$insert=$db->prepare("INSERT INTO quiz_questions(quiz_id,activity_type,question_si,option_a_si,option_b_si,option_c_si,option_d_si,correct_option,explanation_si,display_order,status) VALUES(?,'challenge',?,?,?,?,?,?,?,?,'active')");foreach($questions as $i=>$q){[$text,$o,$correct,$explanation]=$q;$n=$i+1;$insert->bind_param('isssssssi',$quizId,$text,$o[0],$o[1],$o[2],$o[3],$correct,$explanation,$n);if(!$insert->execute())throw new RuntimeException($insert->error);}$quizTitle="$order වන පාඩම — MCQ ප්‍රශ්න 30";$update=$db->prepare("UPDATE quizzes SET title_si=?,timer_minutes=30,pass_mark=50 WHERE id=?");$update->bind_param('si',$quizTitle,$quizId);$update->execute();$count=(int)(query_one("SELECT COUNT(*) total FROM quiz_questions WHERE quiz_id=? AND activity_type='challenge' AND status='active'",'i',[$quizId])['total']??0);if($count!==30)throw new RuntimeException("Lesson $order expected 30 MCQs, found $count.");}
